<template>
	<view class="container">
		<u-loading-page
		:loading="true" 
		v-if="load"
		fontSize="28rpx" />
		<view class="inner" v-else>
			<view class="inner-groups">
				<view class="inner-group">
					<view class="title">基本信息</view>
					<view class="form">
						<view class="form-row">
							<text class="row-left">真实姓名</text>
							<view class="row-input">
								<u-input
								    placeholder="请输入真实姓名"
									border="none"
									:readonly="disabled"
									placeholderClass="placeholder30"
									v-model="form.realname"
								    clearable />
							</view>
						</view>
						<view class="form-row">
							<text class="row-left">出生年月</text>
							<view class="row-center" :class="{'text-grey':form.birthday==null}" @click="showPicker('birthdayShow')">
								{{form.birthday?form.birthday:'未设置'}}
							</view>
						</view>
						<view class="form-row">
							<text class="row-left">性别</text>
							<view class="row-center" :class="{'text-grey':form.gender==0}" @click="showPicker('genderShow')">
								{{getGenderText(form.gender)}}
							</view>
						</view>
						<view class="form-row">
							<text class="row-left">身份证号</text>
							<view class="row-input">
								<u-input
								    placeholder="请输入身份证号"
									border="none"
									:readonly="disabled"
									type="idcard"
									placeholderClass="placeholder30"
									v-model="form.idcard"
								    clearable />
							</view>
						</view>
					</view>
				</view>
				<view class="inner-group">
					<view class="title">个人爱好</view>
					<view class="personal-info">
						<u-textarea
						v-model="form.personal_ah" 
						placeholderClass="placeholder28" 
						:placeholderStyle="placeholderStyle" 
						placeholder="请输入个人爱好" 
						border="none"
						height="120"
						:disabled="disabled"
						:customStyle="{'padding':'0','background':'none'}"/>
					</view>
				</view>
			</view>
			<view class="submit">
				<button type="default" class="submit-btn" @click="submit"
					:disabled="submitDisabled || disabled">{{getBtnText()}}</button>
			</view>
		</view>
		<u-picker 
		:show="genderShow" 
		:defaultIndex="defaultGenderIndex" 
		cancelColor="#959595" 
		confirmColor="#4BBF5A" 
		:columns="genderArr"
		@confirm="genderConfirm"
		@cancel="genderShow = false"/>
		<u-datetime-picker 
		:show="birthdayShow" 
		v-model="birthday" 
		cancelColor="#959595" 
		confirmColor="#4BBF5A" 
		@confirm="birthdayConfirm"
		mode="date"
		:minDate="minDate"
		:maxDate="maxDate"
		:formatter="formatter"
		@cancel="birthdayShow = false"/>
	</view>
</template>

<script>
	var validate = require("@/components/validate/validate.js");
	import md5 from '@/components/MD5.js';
	var _this;
	const d = new Date()
	export default {
		data() {
			return {
				form:{
					step:1,
					realname:'',
					idcard:'',
					birthday:'',
					gender:'',
					personal_ah:'',
				},
				status:0,
				submitDisabled:false,
				placeholderStyle:"color:#959595;",
				genderShow:false,
				genderArr:[
					['男', '女']
				],
				defaultGenderIndex:[],
				birthday:'',
				birthdayShow:false
			}
		},
		onLoad(e) {
			_this = this;
			_this.tijiao()
		},
		methods: {
			getBtnText(){
				if(_this.status == -1){
					return '审核中'
				}else if (_this.status==1) {
					return '已完成认证'
				}else if (_this.status==2) {
					return '更新提交'
				}else{
					return '立即认证'
				}
			},
			showPicker(text){
				if (_this.disabled) {
					return
				}
				_this[text] = true
			},
			getGenderText(gender){
				if (gender==0) {
					return '未设置';
				}
				return gender==1 ? '男' : '女'
			},
			genderConfirm(e){
				const {indexs} = e
				_this.form.gender = indexs[0] + 1
				_this.genderShow = false
			},
			formatter(type, value) {
				if (type === 'year') {
					return `${value}年`
				}
				if (type === 'month') {
					return `${value}月`
				}
				if (type === 'day') {
					return `${value}日`
				}
				return value
			},
			birthdayConfirm(e){
				const timeFormat = uni.$u.timeFormat;
				const {value} = e
				let birthday = timeFormat(value, 'yyyy-mm-dd')
				_this.form.birthday = birthday
				_this.birthdayShow = false
			},
			submit(){
				_this.form.step = 2
				_this.tijiao()
			},
			//提交
			async tijiao(){
				if (_this.form.step == 2) {
					var rule = [
					{
						name: 'realname',
						rules: ['require', 'chn'],
						errorMsg: {
							require: '请输入真实姓名',
							chn: '真实姓名只能为中文',
						}
					},{
						name: 'birthday',
						rules: ['require'],
						errorMsg: {
							require: '请选择出生年月',
						}
					},{
						name: 'gender',
						rules: ['require'],
						errorMsg: {
							require: '请选择性别',
						}
					},{
						name: 'idcard',
						rules: ['require'],
						errorMsg: {
							require: '请输入身份证号',
						}
					},{
						name: 'personal_ah',
						rules: ['require'],
						errorMsg: {
							require: '请输入个人爱好',
						}
					}];
					// 是否全部通过，返回Boolean
					let checked = validate.check(this.form, rule);
					if (!checked) {
						// 获取错误信息
						let err = validate.getError();
						uni.$u.toast(err[0])
						return;
					}
					_this.submitDisabled = true
					setTimeout(()=>{
						_this.submitDisabled = false
					},2000)
				}
				const data = await _this.$post('port/edit_user_rz',_this.form)
				if (data.code==200) {
					uni.$u.toast(data.msg)
					_this.status = -1
				}else if(data.code == -50){
					uni.$u.toast(data.msg,()=>{
						_this.finish()
					})
				}else if(data.code == -1){
					_this.mobile = data.result.mobile
					_this.form.realname = data.result.realname
					_this.form.birthday = data.result.birthday
					_this.birthday = Number(new Date())
					_this.form.gender = data.result.gender
					_this.defaultGenderIndex = [_this.form.gender]
					_this.form.personal_ah = data.result.personal_ah
					_this.form.idcard = data.result.idcard
					_this.status = data.result.status
				
					if (_this.load) {
						_this.load = false
					}
				}else{
					uni.$u.toast(data.msg)
				}
			}
		},
		computed:{
			minDate:{
				cache:false,
				get() {
					let date = `${d.getFullYear() - 100}-01-01`
					return Date.parse(date)
				}
			},
			maxDate:{
				cache:false,
				get() {
					return d.getTime()
				}
			},
			disabled:{
				cache:false,
				get() {
					return this.status == -1 || this.status == 1
				}
			}
		}
	}
</script>

<style lang="scss" scoped>
	@import "static/css/form.scss";
	.container {
		.inner{
			padding: 20rpx 30rpx 0 30rpx;
			.inner-groups{
				.inner-group{
					background: #fff;
					border-radius: $border-radius;
					padding: 0 30rpx 0 30rpx;
					&:not(:last-child){
						margin-bottom: 20rpx;
					}
					.title{
						position: relative;
						line-height: 70rpx;
						font-size: 30rpx;
						font-weight: bold;
						padding-left: 20rpx;
						&::before{
							content: '';
							background: $theme-color;
							width: 8rpx;
							height: 24rpx;
							position: absolute;
							left: 0;
							top: calc(50% - 12rpx);
							border-radius: 6rpx;
						}
					}
					.form{
						background: unset;
						border-radius: unset;
						.form-row{
							padding: 0;
							&:last-child{
								border-bottom: none;
							}
						}
					}
					.personal-info{
						padding:10rpx 0 20rpx 0;
					}
				}
			}
		}
	}
</style>
